function toast(m){var t=document.createElement('div');t.className='toast';t.textContent=m;document.body.appendChild(t);setTimeout(function(){t.style.opacity='0';t.style.transition='opacity .4s';setTimeout(function(){t.remove();},400);},2500);}

// Shared in-app modal replacing native confirm()/alert()/prompt(). Promise-based:
// uiConfirm(msg[,opts]) -> Promise<boolean>, uiAlert(msg[,opts]) -> Promise<void>,
// uiPrompt(msg,default[,opts]) -> Promise<string|null> (null on cancel).
// opts: {title, danger, okText, cancelText, placeholder, password}. Enter=OK, Escape/backdrop=cancel.
function uiEsc_(s){return String(s==null?'':s).replace(/[&<>"]/g,function(c){return c==='&'?'&amp;':c==='<'?'&lt;':c==='>'?'&gt;':'&quot;';});}
function uiModal_(opts){
  opts=opts||{};
  return new Promise(function(resolve){
    var old=document.getElementById('ui-modal');if(old)old.remove();
    var ov=document.createElement('div');ov.id='ui-modal';ov.className='ui-modal-ov';
    var card=document.createElement('div');card.className='ui-modal-card';
    var html='';
    if(opts.title)html+='<div class="ui-modal-title">'+uiEsc_(opts.title)+'</div>';
    if(opts.message)html+='<div class="ui-modal-msg">'+uiEsc_(opts.message)+'</div>';
    card.innerHTML=html;
    // Text-input mode (uiPrompt): a styled field in the same card, OK resolves its value.
    var input=null;
    if(opts.input){
      input=document.createElement('input');
      input.type=opts.password?'password':'text';
      input.value=(opts.defaultValue!=null?String(opts.defaultValue):'');
      if(opts.placeholder)input.placeholder=opts.placeholder;
      input.style.cssText='width:100%;box-sizing:border-box;margin-top:4px;padding:11px 12px;background:var(--s2);border:1px solid var(--b1);border-radius:10px;color:var(--t1);font-size:15px;font-family:inherit;outline:none';
      input.onfocus=function(){input.style.borderColor='#2FA8E0';};
      input.onblur=function(){input.style.borderColor='var(--b1)';};
      card.appendChild(input);
    }
    var btns=document.createElement('div');btns.className='ui-modal-btns';
    var done=false;
    var okVal=function(){return opts.input?(input?input.value:''):true;};
    var cancelVal=function(){return opts.input?null:(opts.confirm?false:true);};
    function finish(v){if(done)return;done=true;document.removeEventListener('keydown',onKey);ov.style.opacity='0';setTimeout(function(){if(ov.parentNode)ov.remove();},150);resolve(v);}
    function onKey(e){if(e.key==='Escape')finish(cancelVal());else if(e.key==='Enter'){if(opts.input)e.preventDefault();finish(okVal());}}
    if(opts.confirm||opts.input){
      var cancel=document.createElement('button');cancel.className='ui-modal-btn ui-modal-cancel';cancel.textContent=opts.cancelText||'Cancel';cancel.onclick=function(){finish(cancelVal());};btns.appendChild(cancel);
    }
    var ok=document.createElement('button');ok.className='ui-modal-btn '+(opts.danger?'ui-modal-danger':'ui-modal-ok');ok.textContent=opts.okText||(opts.confirm?'Confirm':'OK');ok.onclick=function(){finish(okVal());};btns.appendChild(ok);
    card.appendChild(btns);ov.appendChild(card);
    ov.addEventListener('click',function(e){if(e.target===ov)finish(cancelVal());});
    document.addEventListener('keydown',onKey);
    document.body.appendChild(ov);
    requestAnimationFrame(function(){ov.style.opacity='1';});
    setTimeout(function(){try{if(input){input.focus();input.select();}else ok.focus();}catch(_){}},0);
  });
}
function uiConfirm(message,opts){opts=opts||{};return uiModal_({message:message,title:opts.title,confirm:true,danger:opts.danger,okText:opts.okText,cancelText:opts.cancelText});}
function uiAlert(message,opts){opts=opts||{};return uiModal_({message:message,title:opts.title,confirm:false,okText:opts.okText});}
function uiPrompt(message,defaultValue,opts){opts=opts||{};return uiModal_({input:true,message:message,defaultValue:defaultValue,title:opts.title,placeholder:opts.placeholder,password:opts.password,okText:opts.okText||'OK',cancelText:opts.cancelText});}

function updDots(){
  var row=document.getElementById('dots-row');
  if(!row)return;
  // Show dots for all weeks up to current + a few ahead
  var maxW=Math.max(17,cw+3);
  var html='';
  for(var w=1;w<=maxW;w++){
    var s=ws(w),d=Object.values(s.wo).filter(Boolean).length;
    var wc=getWC(w)||6;
    var cls='dot'+(w===cw?' cur':(d>=wc&&wc>0?' done':''));
    html+='<div class="'+cls+'" onclick="GW('+w+', true)" title="Week '+w+'"></div>';
  }
  row.innerHTML=html;
}

function updHdr(){
  var days=['Sun','Mon','Tue','Wed','Thu','Fri','Sat'];var months=['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
  var weekStart=getWeekStartDate(cw);
  var weekEnd=new Date(weekStart); weekEnd.setDate(weekStart.getDate()+6);
  var rangeStr;
  if(weekStart.getMonth()===weekEnd.getMonth()){
    rangeStr=months[weekStart.getMonth()]+' '+weekStart.getDate()+'-'+weekEnd.getDate();
  } else {
    rangeStr=months[weekStart.getMonth()]+' '+weekStart.getDate()+' - '+months[weekEnd.getMonth()]+' '+weekEnd.getDate();
  }
  document.getElementById('btn-wt').innerHTML=rangeStr+' <svg width="10" height="10" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" style="opacity:.4;vertical-align:middle"><path d="m6 9 6 6 6-6"/></svg>';
  var pv=document.getElementById('btn-pv');if(pv)pv.disabled=false;
  var nx=document.getElementById('btn-nx');if(nx)nx.disabled=false;
}

function logWeightQuick(){
  var cur = st.weight || '';
  uiPrompt('Log your weight (lbs)', cur, {title:'Log weight', okText:'Save', placeholder:'e.g. 162.5'}).then(function(val){
    if(val===null) return;
    var num = parseFloat(val);
    if(isNaN(num)||num<=0){ toast('Enter a valid weight'); return; }
    st.weight = num;
    if(!st.weightLog) st.weightLog = [];
    var today = getTodayKey();
    var existing = st.weightLog.find(function(w){return w && w.date===today;});
    // Logging a weight on a date that was previously DELETED revives it - clear the tombstone
    // rather than leaving a deleted flag on a row that now has a real value again.
    if(existing){ existing.weight = num; if(existing.deleted) delete existing.deleted; }
    else st.weightLog.push({date:today, weight:num});
    sv(); fbPush(true);
    toast('Weight logged: '+num+' lbs');
    renderHomeTSSAndPR();
  });
}

// Computes a comparable training-stress number for any activity type.
// Cycling activities with power data already have a real TSS (Coggan formula).
// Everything else (runs, strength, mobility, etc.) falls back to:
//   1. hrTSS - based on avg HR relative to estimated lactate threshold HR
//      (LTHR estimated as 88% of max HR when not otherwise known - a standard
//      approximation, per Friel, when no formal threshold test exists)
//   2. RPE x duration (Foster's session-RPE method) when no HR data exists
// This lets one CTL/ATL/TSB model represent total load across every sport,
// since fatigue from running affects cycling performance and vice versa.
function unifiedLoad(a){
  if(a.tss) return a.tss; // already has real power-based TSS (cycling)

  var durMin = (a.movingSecs ? a.movingSecs/60 : (a.duration ? parseDurToMin(a.duration) : 0));
  var maxHR = parseInt(st.maxHR||172);
  var lthr = Math.round(maxHR*0.88);

  if(a.avgHR && durMin){
    // hrTSS: scales duration by intensity relative to threshold HR, using
    // an exponential weighting similar to TrainingPeaks' hrTSS approach
    var hrRatio = a.avgHR/lthr;
    var intensityFactor = Math.min(1.15, hrRatio); // cap runaway values from anomalous HR spikes
    return Math.round(durMin * intensityFactor * intensityFactor * 100/60);
  }

  if(a.rpe && durMin){
    // Foster session-RPE: duration (min) x RPE (1-10), scaled to sit on a
    // comparable numeric range to cycling TSS (roughly /3)
    return Math.round((durMin * a.rpe) / 3);
  }

  return 0;
}

function parseDurToMin(durStr){
  if(!durStr) return 0;
  var parts = String(durStr).split(':').map(Number);
  if(parts.length===3) return parts[0]*60+parts[1]+parts[2]/60;
  if(parts.length===2) return parts[0]+parts[1]/60;
  return parseFloat(durStr)||0;
}

// ===== RACES: single source of truth =====================================
// st.races is the ONE store. getNextRace_() is the single accessor every
// consumer (dashboards, AI Coach) reads, so there is no more fake/hardcoded
// race data anywhere. Legacy st.events entries are folded in once, then
// st.events is retired. No auto-seeded demo race — an empty list stays empty.
var _racesReady=false;
// Parse 'YYYY-MM-DD' (zero-padded OR not) as a LOCAL date. new Date('2026-7-8')
// is invalid and new Date('2026-07-08') is UTC midnight (drifts a day west of
// GMT) — both bugs this avoids.
function parseRaceDate_(s){
  var p=String(s||'').split('-');
  if(p.length===3){
    var dt=new Date(parseInt(p[0],10), parseInt(p[1],10)-1, parseInt(p[2],10));
    return isNaN(dt)?null:dt;
  }
  var d=new Date(s); return isNaN(d)?null:d;
}
// Best-effort sport for legacy/imported races that predate the sport field.
function raceSportGuess_(name){
  var n=' '+String(name||'').toLowerCase()+' ';
  // NOTE: this whole file is served inside one template literal, so regex
  // backslash-escapes get stripped one level — avoid them here (pad with
  // spaces instead of using word boundaries).
  if(/century|fondo|gravel| crit|cyclo| bike | ride |zwift|watopia|kanza| 100 | 50 /.test(n)) return 'bike';
  if(/marathon|half|10k|5k| run | mile |trail|ultra/.test(n)) return 'run';
  return 'other';
}
// Migrate legacy st.events -> st.races and backfill id/sport. Runs once per
// load (guarded) and only persists when it actually changes something.
function migrateRaces_(){
  if(_racesReady && Array.isArray(st.races)) return;
  var changed=false;
  if(!Array.isArray(st.races)){ st.races=[]; changed=true; }
  // Fold legacy st.events into st.races. Key the "already present" check on a
  // NORMALIZED name|calendar-day (same as the dedup below) and include
  // tombstoned (deleted:true) races. Previously this compared dates by exact
  // string, so a soft-deleted race whose tombstone date format differed from
  // the immortal st.events entry (padding / T00:00:00 / unpadded) failed the
  // check and got re-added un-deleted on every reload — silently resurrecting
  // user deletions. Keying on the normalized day + including tombstones makes
  // the fold idempotent, so it no longer matters that st.events=[] can't
  // survive the Firebase union merge.
  var norm_=function(s){ return String(s||'').toLowerCase().replace(/ +/g,' ').trim(); };
  var raceKey_=function(name,date){ var d=parseRaceDate_(date); var dk=d?(d.getFullYear()+'-'+(d.getMonth()+1)+'-'+d.getDate()):String(date||''); return norm_(name)+'|'+dk; };
  var existingKeys_={};
  st.races.forEach(function(r){ if(r) existingKeys_[raceKey_(r.name,r.date)]=true; });
  if(Array.isArray(st.events) && st.events.length){
    st.events.forEach(function(e){
      if(!e || !e.date) return;
      var ek=raceKey_(e.name,e.date);
      if(existingKeys_[ek]) return;   // present live OR tombstoned — never re-add
      st.races.push({id:e.id||('race-'+Date.now()+'-'+st.races.length),
        name:e.name||'Race', date:e.date, sport:raceSportGuess_(e.name),
        distance:null, goal:(e.type==='goal'?'Goal':'Finish Strong'), target:'', location:'', status:'active'});
      existingKeys_[ek]=true;
      changed=true;
    });
  }
  if(st.events && st.events.length){ st.events=[]; changed=true; } // best-effort retire; harmless now that the fold is idempotent
  st.races.forEach(function(r,i){
    if(!r.id){ r.id='race-'+(r.date||'x')+'-'+i; changed=true; }
    if(!r.sport){ r.sport=raceSportGuess_(r.name); changed=true; }
    if(r.status==null){ r.status='active'; changed=true; }   // status: active | tentative | cancelled
  });
  // Collapse duplicate races (same name + same calendar date) that earlier
  // seeds/migrations left behind — e.g. Grand Rapids Half seeded into both
  // st.races and the old st.events. IMPORTANT: mark the extras deleted:true
  // (a tombstone) rather than splicing them out. A splice does not survive the
  // Firebase merge — the duplicate has its own id, so mergeArrays_ re-unions it
  // from remote on the next sync (which is why the earlier hard dedup "didn't
  // work"). A deleted flag OR-merges to true and sticks. Date is normalized
  // through parseRaceDate_ so format variants (padding / T00:00:00 / unpadded)
  // still count as the same day. No backslash regex (template literal strips it).
  var _seen={};
  st.races.forEach(function(r){
    if(r.deleted) return; // don't resurrect already-tombstoned races
    var d=parseRaceDate_(r.date);
    var dk=d?(d.getFullYear()+'-'+(d.getMonth()+1)+'-'+d.getDate()):String(r.date||'');
    var k=String(r.name||'').toLowerCase().replace(/ +/g,' ').trim()+'|'+dk;
    if(_seen[k]){ r.deleted=true; changed=true; }   // keep the first, tombstone the rest
    else _seen[k]=true;
  });
  _racesReady=true;
  if(changed){ try{ sv(); }catch(e){} }
}
// All upcoming races (today or later), soonest first, normalized. The _i field
// is the index into st.races so edit/delete can target the exact entry.
// Cancelled races are EXCLUDED by default so they drop out of every countdown,
// taper narrative, and coach premise (Jul 18 report #5). Pass includeCancelled
// to list them (management views render them struck-through so they can be
// restored). status: 'active' | 'tentative' | 'cancelled'.
function upcomingRaces_(includeCancelled){
  migrateRaces_();
  var today=new Date(); today.setHours(0,0,0,0);
  return (st.races||[]).map(function(r,i){
    var d=parseRaceDate_(r.date);
    var daysOut=d?Math.round((d-today)/86400000):null;
    return {id:r.id, name:r.name||'Race', date:r.date, sport:r.sport||'other',
      distance:(r.distance!=null?r.distance:null), goal:r.goal||'Finish Strong',
      target:r.target||'', location:r.location||'', status:r.status||'active', dateObj:d,
      daysOut:daysOut, weeksOut:(daysOut!=null?Math.ceil(daysOut/7):null), _i:i, _deleted:!!r.deleted};
  }).filter(function(x){ return !x._deleted && (includeCancelled || x.status!=='cancelled') && x.dateObj && x.daysOut>=0; })
    .sort(function(a,b){ return a.dateObj-b.dateObj; });
}
// The single accessor: soonest upcoming race, normalized, or null.
function getNextRace_(){
  var up=upcomingRaces_();
  return up.length?up[0]:null;
}
// Kept for older callers; now just ensures the store is migrated.
function ensureEvents(){ migrateRaces_(); }

function eventsCardHTML(){
  var next = getNextRace_();
  if(!next) return '';
  var icon = next.sport==='bike'?'🚴':next.sport==='run'?'🏃':'🏁';
  return '<div onclick="openRaceEditor('+next._i+')" style="margin:0 16px 12px;background:linear-gradient(135deg,rgba(15,110,86,.12),rgba(15,110,86,.04));border:1px solid rgba(15,110,86,.25);border-radius:14px;padding:14px 16px;cursor:pointer">'
    + '<div style="font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:.06em;color:#0F6E56;margin-bottom:4px">'+icon+' '+next.name+'</div>'
    + '<div style="display:flex;align-items:baseline;gap:8px">'
    + '<div style="font-size:28px;font-weight:900;color:var(--t1)">'+next.daysOut+'</div>'
    + '<div style="font-size:13px;color:var(--t2)">days out · '+next.weeksOut+' weeks'+(next.target?' · target '+next.target:'')+'</div>'
    + '</div></div>';
}

function openEventEdit(){
  var modal = document.getElementById('mod-SERVICE');
  modal.innerHTML = '';
  modal.style.cssText = 'align-items:center;justify-content:center;padding:20px';

  var card = document.createElement('div');
  card.style.cssText = 'background:var(--s1);border-radius:16px;width:100%;max-width:320px;padding:22px 20px;box-shadow:0 8px 32px rgba(0,0,0,.3)';

  var title = document.createElement('div');
  title.style.cssText = 'font-size:17px;font-weight:800;color:var(--t1);margin-bottom:16px';
  title.textContent = 'Add Event';
  card.appendChild(title);

  function makeField(labelText, placeholder, type, defaultVal){
    var wrap = document.createElement('div');
    wrap.style.cssText = 'margin-bottom:12px';
    var lbl = document.createElement('div');
    lbl.style.cssText = 'font-size:12px;font-weight:600;color:var(--t3);margin-bottom:5px';
    lbl.textContent = labelText;
    var input = document.createElement('input');
    input.type = type||'text';
    input.placeholder = placeholder||'';
    if(defaultVal!=null) input.value = defaultVal;
    input.style.cssText = 'width:100%;padding:10px 12px;background:var(--s2);border:1px solid var(--b1);border-radius:10px;color:var(--t1);font-size:14px;font-family:inherit';
    wrap.appendChild(lbl);
    wrap.appendChild(input);
    card.appendChild(wrap);
    return input;
  }

  var nameInput = makeField('Event name', 'e.g. Grand Rapids Half');
  var dateInput = makeField('Date', 'YYYY-MM-DD', 'date');

  var typeWrap = document.createElement('div');
  typeWrap.style.cssText = 'margin-bottom:12px';
  var typeLbl = document.createElement('div');
  typeLbl.style.cssText = 'font-size:12px;font-weight:600;color:var(--t3);margin-bottom:5px';
  typeLbl.textContent = 'Type';
  var typeSelect = document.createElement('select');
  typeSelect.style.cssText = 'width:100%;padding:10px 12px;background:var(--s2);border:1px solid var(--b1);border-radius:10px;color:var(--t1);font-size:14px;font-family:inherit';
  ['race','goal'].forEach(function(opt){
    var o = document.createElement('option'); o.value = opt; o.textContent = opt==='race'?'Race':'Goal'; typeSelect.appendChild(o);
  });
  typeWrap.appendChild(typeLbl); typeWrap.appendChild(typeSelect);
  card.appendChild(typeWrap);

  var actions = document.createElement('div');
  actions.style.cssText = 'display:flex;gap:8px;margin-top:8px';

  var cancelBtn = document.createElement('button');
  cancelBtn.textContent = 'Cancel';
  cancelBtn.style.cssText = 'flex:1;padding:11px;background:var(--s2);border:1px solid var(--b1);border-radius:10px;color:var(--t1);font-size:14px;font-weight:700;cursor:pointer';
  cancelBtn.addEventListener('click', function(){ closeServiceModal(); });

  var saveBtn = document.createElement('button');
  saveBtn.textContent = 'Add Event';
  saveBtn.style.cssText = 'flex:1;padding:11px;background:#FC4C02;border:none;border-radius:10px;color:#fff;font-size:14px;font-weight:700;cursor:pointer';
  saveBtn.addEventListener('click', function(){
    var name = nameInput.value.trim();
    if(!name){ nameInput.style.borderColor='#E24B4A'; return; }
    var dateStr = dateInput.value;
    if(!dateStr || !/^\\d{4}-\\d{2}-\\d{2}$/.test(dateStr)){ dateInput.style.borderColor='#E24B4A'; return; }
    migrateRaces_();
    st.races.push({id:'race-'+Date.now(), name:name, date:dateStr, sport:raceSportGuess_(name),
      distance:null, goal:(typeSelect.value==='goal'?'Goal':'Finish Strong'), target:'', location:''});
    sv();
    closeServiceModal();
    renderHomeTSSAndPR();
    toast('Event added');
  });

  actions.appendChild(cancelBtn);
  actions.appendChild(saveBtn);
  card.appendChild(actions);

  modal.appendChild(card);
  modal.classList.add('open');
  document.body.style.overflow = 'hidden';
}

// Achievements: real PR history instead of only-detects-if-happened-today
// logic, plus a simple streak counter. Existing longest-ride/best-NP/highest-TSS
// detection logic (from the disabled home function) is reused here, now
// feeding a persistent st.achievements log instead of a transient banner.
function checkForNewAchievements(){
  var rides = (st.rides||[]).filter(function(r){ return !r.deleted; });
  if(!rides.length) return;
  if(!st.achievements) st.achievements = [];

  var longestRide=0, bestNP=0, highestTSS=0;
  // Sanity ceilings: values above these are corrupted/malformed data, not
  // real rides. NP above 600W and TSS above 600 are outside anything a real
  // human ride produces (even elite pro efforts), so we exclude them rather
  // than let a bad data point post a bogus PR banner.
  var NP_CEILING = 600, TSS_CEILING = 600;
  rides.forEach(function(r){
    if(parseFloat(r.distance||0)>longestRide) longestRide=parseFloat(r.distance||0);
    if(r.np && r.np>bestNP && r.np<=NP_CEILING) bestNP=r.np;
    // constRideTSS_, not the flat TSS_CEILING: 600 is below a real hard century (the Holland 100
    // scored 699 over 6h49m) so the ceiling was discarding genuine rides as well as corrupt ones.
    var _rt7=(typeof constRideTSS_==='function')?constRideTSS_(r):null; if(_rt7 && _rt7>highestTSS) highestTSS=_rt7;
  });

  function recordIfNew(key, label, value){
    var existing = st.achievements.find(function(a){ return a.key===key; });
    if(!existing || value > existing.value){
      st.achievements = st.achievements.filter(function(a){ return a.key!==key; });
      st.achievements.unshift({key:key, label:label, value:value, date:getTodayKey()});
      return true;
    }
    return false;
  }

  var changed = false;
  if(longestRide>0) changed = recordIfNew('longest_ride', 'Longest ride: '+longestRide.toFixed(1)+' mi', longestRide) || changed;
  if(bestNP>0) changed = recordIfNew('best_np', 'Best NP: '+bestNP+'W', bestNP) || changed;
  if(highestTSS>0) changed = recordIfNew('highest_tss', 'Highest TSS: '+highestTSS, highestTSS) || changed;

  if(changed) sv();
}

function achievementsCardHTML(){
  checkForNewAchievements();
  if(!st.achievements || !st.achievements.length) return '';
  var today = getTodayKey();
  var newToday = st.achievements.filter(function(a){ return a.date===today; });
  if(!newToday.length) return '';

  var h = '<div style="margin:0 16px 12px;background:var(--s2);border-radius:14px;padding:12px 14px">'
    + '<div style="font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:.06em;color:#FC4C02;margin-bottom:6px">🏆 New Personal Record!</div>';
  newToday.forEach(function(a){
    h += '<div style="font-size:13px;font-weight:700;color:var(--t1);padding:2px 0">'+a.label+'</div>';
  });
  h += '</div>';
  return h;
}

// ===== Dashboard redesign: greeting, weather, nutrition, weight, today's workout =====

function greetingHTML(){
  var h = new Date().getHours();
  var greeting = h<12 ? 'Good morning' : h<17 ? 'Good afternoon' : 'Good evening';
  var name = st.name || 'Mikey';
  var dateStr = new Date().toLocaleDateString('en-US', {weekday:'long', month:'long', day:'numeric'});
  return '<div style="padding:16px 16px 6px">'
    + '<div style="font-size:13px;color:var(--t3);margin-bottom:2px">'+dateStr+'</div>'
    + '<div style="font-size:24px;font-weight:800;color:var(--t1)">'+greeting+', '+name+'</div>'
    + '</div>';
}

// Weather + Form stat row - two-up cards matching the visual weight of
// "the two numbers that most determine today's ride." Weather tile is
// clickable and jumps straight to the full Weather screen (showWeather()).
function weatherFormRowHTML(){
  var wxId = 'wx-stat-'+Date.now();

  var activitiesForForm = (st.rides||[]).filter(function(r){ return !r.deleted; })
    .concat((st.runs||[]).map(function(r){ return {date:r.date, avgHR:r.avgHR, duration:r.time, rpe:r.rpe, deleted:false}; }));
  activitiesForForm.forEach(function(a){ a.load = unifiedLoad(a); });
  var withLoad = activitiesForForm.filter(function(a){ return a.load>0; });
  var formHTML;
  if(withLoad.length < 5){
    formHTML = '<div style="font-size:13px;color:var(--t2);margin-top:2px">Log more rides for a form reading</div>';
  } else {
    var tsb = getFitness_().tsb;
    var formColor = tsb >= 10 ? '#5DCAA5' : tsb >= -10 ? '#4D9FFF' : tsb >= -25 ? '#EF9F27' : '#E24B4A';
    var formLabel = tsb >= 10 ? 'Fresh, good day to push' : tsb >= -10 ? 'Steady state' : tsb >= -25 ? 'Fatigue building' : 'Prioritize recovery';
    formHTML = '<div style="font-size:20px;font-weight:800;color:'+formColor+'">'+(tsb>=0?'+':'')+tsb+'</div>'
      + '<div style="font-size:11px;color:var(--t2);margin-top:2px">'+formLabel+'</div>';
  }

  getWeather_().then(function(wres){
    var d = wres.data;
    var el = document.getElementById(wxId);
    if(!el || !d || !d.current) return;
    var temp = Math.round(d.current.temperature_2m);
    var wind = Math.round(d.current.windspeed_10m);
    var rain = d.current.precipitation_probability;
    el.innerHTML = '<div style="font-size:20px;font-weight:800;color:var(--t1)">'+temp+'&deg;</div>'
      + '<div style="font-size:11px;color:var(--t2);margin-top:2px">Wind '+wind+'mph'+(rain!=null?' &middot; '+rain+'% rain':'')+'</div>';
  }).catch(function(){
    var el = document.getElementById(wxId);
    if(el) el.innerHTML = '<div style="font-size:13px;color:var(--t3)">Weather unavailable</div>';
  });

  return '<div style="display:grid;grid-template-columns:1fr 1fr;gap:10px;margin:0 16px 14px">'
    + '<div id="'+wxId+'" onclick="showWeather()" style="background:var(--s2);border-radius:14px;padding:12px 14px;cursor:pointer">'
    + '<div style="font-size:10px;color:var(--t3);font-weight:700;text-transform:uppercase;letter-spacing:.05em;margin-bottom:4px">Weather</div>'
    + 'Loading&hellip;</div>'
    + '<div style="background:var(--s2);border-radius:14px;padding:12px 14px">'
    + '<div style="font-size:10px;color:var(--t3);font-weight:700;text-transform:uppercase;letter-spacing:.05em;margin-bottom:4px">Form</div>'
    + formHTML
    + '</div></div>';
}

// Live AI-generated coach note - the hero card on Home. Fresh every visit
// (no caching), same context model as the full AI Coach screen but
// condensed to 1-2 sentences. Given hero visual treatment (purple-tinted,
// largest text on the page) since it's the single most important thing to
// read at a glance.
function coachNoteHTML(){
  var id = 'coach-note-'+Date.now();
  setTimeout(function(){ fetchCoachNote(id); }, 0);
  return '<div style="margin:0 16px 14px;background:linear-gradient(135deg,rgba(168,85,247,.14),rgba(168,85,247,.03));border:1px solid rgba(168,85,247,.28);border-radius:18px;padding:16px 18px">'
    + '<div style="font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:.06em;color:#c084fc;margin-bottom:8px">Coach</div>'
    + '<div id="'+id+'" style="font-size:17px;font-weight:600;color:var(--t1);line-height:1.35">Thinking&hellip;</div>'
    + '</div>';
}

function fetchCoachNote(elId){
  var el = document.getElementById(elId);
  if(!el) return;

  getWeather_().then(function(wres){
    var wxData = wres.data;
    var wx = wxData && wxData.current;
    var weatherStr = wx
      ? Math.round(wx.temperature_2m)+'F, wind '+Math.round(wx.windspeed_10m)+'mph from '+['N','NE','E','SE','S','SW','W','NW'][Math.round((wx.winddirection_10m||0)/45)%8]+(wx.precipitation_probability!=null?', '+wx.precipitation_probability+'% rain':'')
      : 'unavailable';

    wxCoachHazard_(wx, function(_aq){
    fetchTodaysDecision(weatherStr+_aq, function(err, decisionText){
      var target = document.getElementById(elId);
      if(!target) return;
      target.textContent = (err || !decisionText) ? 'Coach unavailable right now.' : decisionText;
    });
    });
  })
  .catch(function(){
    fetchTodaysDecision('unavailable', function(err, decisionText){
      var target = document.getElementById(elId);
      if(!target) return;
      target.textContent = (err || !decisionText) ? 'Coach unavailable right now.' : decisionText;
    });
  });
}

// Today's single workout card - clones today's real wo-card from the full
// week view (with its live checkbox/swap/log buttons intact) rather than
// rebuilding workout logic separately, so behavior stays identical. Given a
// left accent bar to read as "the next action," distinct from the stat cards.
// SHARED Today's-Plan / session card. Resolves the prescription through planResolve_ (derive-at-
// render, priced to current FTP) so both Home surfaces show the same content: name, ride band + %
// of FTP + HR + duration + TSS, or the movement list (sets x reps @ %1RM), plus the note. Rest
// renders distinctly. Tapping opens the day editor for THAT session. One function, both renderers.
// Open a YouTube SEARCH for a movement name. Search-by-name rather than stored links: the
// exercise arrays carry no link field, so this covers every movement including ones added
// later, with zero data entry — and curated per-movement links go stale and get lost.
function watchExercise_(q){
  try{
    var name=decodeURIComponent(String(q||'')).trim();
    if(!name) return;
    window.open('https://www.youtube.com/results?search_query='+encodeURIComponent(name), '_blank', 'noopener');
  }catch(e){ try{ console.error('[watch]', e && e.message); }catch(_e){} }
}
// THE shared planned-exercise row. Every surface that lists prescribed movements renders
// through this ONE function. That is deliberate durability: the Watch button has been lost
// three times across rebuilds by living in per-surface copies, so it lives here and any
// future surface inherits it by construction rather than by remembering to re-add it.
// ==================== Anatomy body map ====================
// Data + highlight + legend + the silhouette body art. Every muscle group is a <g id="m-f-*/m-b-*"
