// Normalize an exercise name so a library key resolves despite casing / punctuation / parenthetical
// variants ('Bird dog' vs 'Bird-dog'). Non-alphanumerics collapse to single spaces. Regex whitespace
// and word-boundary escapes are avoided on purpose — the served template literal eats them.
function _anatKey_(name){ var s=String(name==null?'':name).toLowerCase().replace(/[^a-z0-9]+/g,' '); return s.replace(/^ +/,'').replace(/ +$/,'').replace(/  +/g,' '); }
// Spelling aliases ONLY — a legacy surface's name for a movement the map ALREADY holds. This is not
// a place to add movements: an entry here must resolve to an existing key, so it carries no new
// muscle assignments. Anything that would need its own anatomy (Bench Press, Back Squat, Plank, the
// rest of the FBA/FBB/CORE_EX list) stays unmapped until those assignments are authored.
var ANATOMY_ALIAS={
  'romanian deadlift rdl':'Romanian deadlift',
  // ---- Swap-dropdown alternates that are the SAME movement under another name. Reviewed; each
  // resolves to an existing key, so none of these carry new muscle assignments.
  'pull up':'Pull-up / Lat Pulldown',
  // Spelling only: Strength C names the bar explicitly. Same movement, same muscles.
  'barbell bench press':'Bench press',
  'band pulldown':'Pull-up / Lat Pulldown',
  'pallof press band':'Pallof press',
  'band pallof press':'Pallof press',
  'band woodchop':'Woodchop',
  'band push up':'Push-up',
  'incline push up':'Push-up',
  'decline push up feet on box':'Push-up',
  'deficit push up on box':'Push-up',
  'push up on box':'Push-up',
  'med ball push up':'Push-up',
  'incline bench press':'Bench press',
  'stability ball dumbbell press':'Dumbbell press',
  'dumbbell floor press':'Dumbbell press',
  'stability ball db row':'Dumbbell Row',
  'band hip thrust':'Glute bridge',
  'incline dumbbell press':'Dumbbell press'
};
var _ANAT_IDX_=null;
function _anatFor_(name){
  if(!name) return null;
  if(ANATOMY_MAP[name]) return ANATOMY_MAP[name];
  if(!_ANAT_IDX_){ _ANAT_IDX_={}; for(var n in ANATOMY_MAP){ if(Object.prototype.hasOwnProperty.call(ANATOMY_MAP,n)) _ANAT_IDX_[_anatKey_(n)]=ANATOMY_MAP[n]; } }
  var k=_anatKey_(name);
  if(_ANAT_IDX_[k]) return _ANAT_IDX_[k];
  var al=ANATOMY_ALIAS[k];
  return al?(ANATOMY_MAP[al]||null):null;
}
// Combine one or more exercises into a single highlight set. Primary wins over secondary (spec §5); a
// muscle that is 'working' anywhere wins over 'lengthening' (so a mixed movement never reads two ways).
function _anatCombined_(exercises){
  var pri={}, sec={}, len={}, any=false;
  (exercises||[]).forEach(function(e){
    var m=_anatFor_(e && e.name); if(!m) return; any=true;
    (m.pri||[]).forEach(function(id){ pri[id]=1; });
    (m.sec||[]).forEach(function(id){ sec[id]=1; });
    (m.len||[]).forEach(function(id){ len[id]=1; });
  });
  var P=Object.keys(pri), S=Object.keys(sec).filter(function(id){ return !pri[id]; }),
      L=Object.keys(len).filter(function(id){ return !pri[id] && !sec[id]; });
  return { pri:P, sec:S, len:L, mapped:any };
}
function _anatOne_(name){ var m=_anatFor_(name); if(!m) return {pri:[],sec:[],len:[],mapped:false};
  return { pri:(m.pri||[]).slice(), sec:(m.sec||[]).filter(function(id){return (m.pri||[]).indexOf(id)<0;}),
           len:(m.len||[]).filter(function(id){return (m.pri||[]).indexOf(id)<0 && (m.sec||[]).indexOf(id)<0;}), mapped:true }; }
// ---- Body art (v6): the real anatomical figures, front + back.
// Rebuilt from a licensed anatomical illustration (Muscles_front_and_back.svg) rather than drawn
// from primitives. The CONTRACT is unchanged: every group is still a <g id="m-f-*/m-b-*" class="m">,
// so ANATOMY_MAP, the class-swap highlight, the legend and every mount keep working untouched —
// only the shapes inside the groups changed.
//
// The figures are PRE-BAKED strings, not assembled at render time. The source drew each figure as
// one half plus a mirrored <use>, and used FIVE slightly different mirror axes; the build reuses
// those exact matrices instead of re-mirroring about a single guessed axis, which is what keeps the
// centreline free of seams. Paint order is the illustrator's too (groups interleaved with the body
// by source document order), which is why the deltoid still sits over the pectoral's upper border.
//
// Five of the 28 ids have no dedicated path in the source, because it is a SUPERFICIAL illustration:
//   m-b-rhomboid                     deep, under the trapezius — the one shape authored by hand
//   m-b-traps-upper / m-b-traps-mid  one trapezius, split at the scapular spine by clip band
//   m-f-delt-front  / m-f-delt-side  one deltoid, split at the deltopectoral line
//   m-f-hip-flexor                   iliopsoas is deep; mapped to the proximal thigh (rec fem / TFL)
//   m-f-serratus                     drawn as STROKE lines, so this group highlights by stroke
//                                    (.m.pri path.ln and its sec/len twins in the CSS)
// The band splits are clip rects, so both ids of a pair share the one real outline and can never
// disagree about the muscle's shape. Those clipPaths live in the SHARED defs block with the
// gradients — see ANAT_DEFS_SVG — because several diagrams can be on screen at once and per-diagram
