// Stop-the-bleeding: pause the 5s Firebase poll so remote's stale tombstones can't be
// re-merged onto local (mergeState_ deletions-win). Runtime only — NO data mutation.
// NOTE: a page RELOAD re-runs the boot fetch and will re-clobber again until REMOTE is
// cleaned; this only freezes the current session. Run aiResumeSync_() to restart.
function aiPauseSync_(){
  try{ if(typeof fbPollTimer!=='undefined' && fbPollTimer){ clearInterval(fbPollTimer); fbPollTimer=null; console.log('[sync] PAUSED — 5s poll stopped; remote can no longer re-tombstone local this session. Do NOT reload (boot re-merges). aiResumeSync_() to restart.'); } else { console.log('[sync] no active poll timer found'); } }catch(e){ console.log('[sync] pause error '+(e&&e.message)); }
}
function aiResumeSync_(){
  try{ if(typeof initFirebaseSync==='function'){ initFirebaseSync(); console.log('[sync] RESUMED — Firebase poll restarted.'); } }catch(e){ console.log('[sync] resume error '+(e&&e.message)); }
}
// Recovery PREVIEW from the backup. For each backup-unique ride not live locally,
// decide the source: revive a tombstoned IDB copy at its date+dist (preferred — keeps
// GPS/streams), else add it from the backup. Keeps post-backup live rides. Read-only.
function _recoverPreview_(backup){
  if(!backup||!backup.length){ console.log('[rcv] no rides in backup file'); return; }
  var DUR_TOL=90;
  var key_=function(r){ return (r.date||'')+'|'+Math.round((+r.distance||0)*10); };
  var durClose=function(a,b){ return (a>0&&b>0)?(Math.abs(a-b)<=DUR_TOL):true; };
  var rich_=function(r){ var s=0; if(r.stravaId)s+=1000; if((r.lats&&r.lats.length)||(r.gpsLats&&r.gpsLats.length))s+=500; if(r.streams)s+=250; return s+Object.keys(r).length; };
  var all=(st.rides||[]);
  var live=all.filter(function(r){return r&&!r.deleted;});
  var liveKeyset={}; live.forEach(function(r){ liveKeyset[key_(r)]=1; });
  var deadByKey={}; all.forEach(function(r){ if(r&&r.deleted){ var k=key_(r); (deadByKey[k]=deadByKey[k]||[]).push(r); } });
  var bGroups={}; backup.forEach(function(r){ if(r){ var k=key_(r); (bGroups[k]=bGroups[k]||[]).push(r); } });
  var covered=0, reviveIDB=0, addBackup=0, usedDeadKey={};
  Object.keys(bGroups).forEach(function(k){
    var gr=bGroups[k], used=[];
    for(var i=0;i<gr.length;i++){
      if(used[i]) continue; used[i]=1;
      var bd=_durSec_(gr[i]);
      for(var j=i+1;j<gr.length;j++){ if(!used[j] && durClose(bd, _durSec_(gr[j]))) used[j]=1; }
      if(liveKeyset[k]){ covered++; continue; }               // already live
      var dead=deadByKey[k]||[];
      if(dead.length && !usedDeadKey[k]){ reviveIDB++; usedDeadKey[k]=1; }   // un-tombstone IDB copy
      else addBackup++;                                                       // add from backup file
    }
  });
  var postBackup=0, bKeyset={}; backup.forEach(function(r){ if(r) bKeyset[key_(r)]=1; });
  live.forEach(function(r){ if(!bKeyset[key_(r)]) postBackup++; });
  var uniqueFixed=covered+reviveIDB+addBackup;
  // PROVE the shortfall: recompute backup-unique with the OLD NaN-prone dedup
  // (movingSecs||duration; a string duration makes abs(NaN) fail to cluster) so the
  // difference from the fixed _durSec_ dedup = string-duration dupes the 2599 over-counted.
  var oldDur=function(r){ return r.movingSecs||r.duration||0; };
  var oldUnique=0;
  Object.keys(bGroups).forEach(function(k){ var gr=bGroups[k], u=[];
    for(var i=0;i<gr.length;i++){ if(u[i]) continue; u[i]=1; var a=oldDur(gr[i]);
      for(var j=i+1;j<gr.length;j++){ if(!u[j]){ var b=oldDur(gr[j]); if((a&&b)?(Math.abs(a-b)<=DUR_TOL):true) u[j]=1; } }
      oldUnique++; }
  });
  console.log('[rcv] PREVIEW (read-only) — live-local now=' + Number(live.length));
  console.log('[rcv] backup-rows=' + Number(backup.length) + ' -> UNIQUE(fixed dedup)=' + Number(uniqueFixed) + ' | UNIQUE(old NaN dedup)=' + Number(oldUnique) + ' -> the ' + Number(oldUnique-uniqueFixed) + ' difference = string-duration cross-source dupes the 2599 over-counted (now correctly collapsed)');
  console.log('[rcv] split: covered(' + Number(covered) + ') + revive-from-IDB(' + Number(reviveIDB) + ') + add-from-backup(' + Number(addBackup) + ') = ' + Number(uniqueFixed) + ' -> every backup ride accounted, none dropped');
  console.log('[rcv] post-backup rides kept=' + Number(postBackup));
  console.log('[rcv] projected-live-after-recovery=' + Number(uniqueFixed + postBackup) + ' = unique(' + Number(uniqueFixed) + ') + post-backup(' + Number(postBackup) + '); NO CHANGES MADE');
}
// STAGE 1 executor: pause poll, BLOCK gps-migrate, revive-from-IDB / add-from-backup
