function _yvyAddMonth_(k,d){ var p=String(k).split('-'); var t=(parseInt(p[0],10)*12+parseInt(p[1],10)-1)+d; return Math.floor(t/12)+'-'+('0'+(t%12+1)).slice(-2); }
