  if(!lv) return '<span style="color:#8b95a6">Checking today&rsquo;s leaderboard&hellip;</span>';
  if(lv.err) return '<span style="color:#b45309">Placement unavailable &mdash; '+aiEsc_(lv.err)+'</span>';
