  H+='<div style="display:flex;align-items:flex-start;justify-content:space-between;gap:16px;flex-wrap:wrap">';
  H+='<div style="min-width:0">'
    +'<div style="'+LBL+';color:'+SA_MAP_COL.kom+'">Crowns held</div>'
