function getMobDay(k){
  if(!st.mob) st.mob={};
  if(!st.mob[k]) st.mob[k]={done:{},notes:''};
  return st.mob[k];
}

function getMobStreak(){
  var streak=0;
  var d=new Date();
  for(var i=0;i<365;i++){
    var dt=new Date(d); dt.setDate(d.getDate()-i);
    var k=dt.getFullYear()+'-'+(dt.getMonth()+1)+'-'+dt.getDate();
    var day=getMobDay(k);
    var doneCount=Object.values(day.done).filter(Boolean).length;
    if(doneCount>=6) streak++;
    else if(i>0) break;
  }
  return streak;
}

function renderMob(){
  var today=getTodayKey();
  var day=getMobDay(today);
  var doneCount=Object.values(day.done).filter(Boolean).length;
  var total=MOB_EX.length;
  var streak=getMobStreak();
  var pct=Math.round(doneCount/total*100);

  var container=document.getElementById('MOB');
  container.innerHTML='';

  // Header
  var hdr=document.createElement('div');
  hdr.style.cssText='padding:16px 16px 0;';
  hdr.innerHTML='';
  container.appendChild(hdr);
  document.getElementById('mob-back').onclick=function(){showScreen('TRAIN');};

  // Title row
  var title=document.createElement('div');
  title.style.cssText='padding:12px 16px 4px;display:flex;align-items:center;justify-content:space-between';
  title.innerHTML='<div style="font-size:22px;font-weight:800;color:var(--t1)">Daily Mobility</div>'
    +'<div style="text-align:right"><div style="font-size:20px;font-weight:800;color:var(--green)">'+streak+'</div>'
    +'<div style="font-size:10px;color:var(--t3);text-transform:uppercase;letter-spacing:.5px">day streak</div></div>';
  container.appendChild(title);

  // Progress bar
  var progWrap=document.createElement('div');
  progWrap.style.cssText='padding:8px 16px 16px';
  progWrap.innerHTML='<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:6px">'
    +'<div style="font-size:12px;color:var(--t3)">Today&#39;s progress</div>'
    +'<div style="font-size:12px;font-weight:700;color:var(--t2)">'+doneCount+' / '+total+'</div></div>'
    +'<div style="background:var(--s3);border-radius:6px;height:6px;overflow:hidden">'
    +'<div style="background:var(--green);height:100%;border-radius:6px;width:'+pct+'%;transition:width .3s"></div></div>';
  container.appendChild(progWrap);

  // Group by goal
  var groups={};
  MOB_EX.forEach(function(ex,i){
    var g=ex[3];
    if(!groups[g]) groups[g]=[];
    groups[g].push({ex:ex,i:i});
  });

  Object.keys(MOB_GOALS).forEach(function(gk){
    if(!groups[gk]) return;
    var sec=document.createElement('div');
    sec.style.cssText='padding:0 16px;margin-bottom:8px';

    var secHdr=document.createElement('div');
    secHdr.style.cssText='font-size:11px;font-weight:700;color:var(--t3);text-transform:uppercase;letter-spacing:.8px;padding:10px 0 6px';
    secHdr.textContent=MOB_GOALS[gk];
    sec.appendChild(secHdr);

    groups[gk].forEach(function(item){
      var ex=item.ex; var idx=item.i;
      var done=day.done[idx]||false;

      var card=document.createElement('div');
      card.style.cssText='background:var(--s2);border-radius:14px;padding:14px;margin-bottom:8px;border:1px solid '+(done?'rgba(0,200,150,.3)':'var(--b2)')+';transition:all .2s';

      var row=document.createElement('div');
      row.style.cssText='display:flex;align-items:center;gap:12px';

      var chk=document.createElement('div');
      chk.style.cssText='width:26px;height:26px;border-radius:50%;border:2px solid '+(done?'var(--green)':'rgba(255,255,255,.2)')+';display:flex;align-items:center;justify-content:center;flex-shrink:0;cursor:pointer;background:'+(done?'var(--green)':'transparent')+';transition:all .2s';
      if(done) chk.innerHTML='<svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="white" stroke-width="3"><polyline points="20 6 9 17 4 12"/></svg>';

      var info=document.createElement('div');
      info.style.cssText='flex:1;min-width:0';
      var nameStyle='font-size:14px;font-weight:700;color:'+(done?'var(--t3)':'var(--t1)')+';text-decoration:'+(done?'line-through':'none');
      info.innerHTML='<div style="'+nameStyle+';display:flex;align-items:center;gap:6px">'+ex[0]+'<a href="https://www.youtube.com/results?search_query='+encodeURIComponent(ex[0]+' mobility stretch tutorial')+'" target="_blank" style="font-size:10px;color:#FF0000;text-decoration:none;font-weight:600">▶</a></div>'
        +'<div style="font-size:11px;color:var(--orange);font-weight:600;margin-top:1px">'+ex[1]+'</div>'
        +'<div style="font-size:11px;color:var(--t3);margin-top:2px;line-height:1.4">'+ex[2]+'</div>';

      row.appendChild(chk); row.appendChild(info);
      card.appendChild(row);
      sec.appendChild(card);

      (function(capIdx, capCard, capChk, capInfo, capEx){
        function toggleMob(){
          day.done[capIdx]=!day.done[capIdx];
          sv();
          var d=day.done[capIdx];
          capChk.style.background=d?'var(--green)':'transparent';
          capChk.style.borderColor=d?'var(--green)':'rgba(255,255,255,.2)';
          capChk.innerHTML=d?'<svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="white" stroke-width="3"><polyline points="20 6 9 17 4 12"/></svg>':'';
          capCard.style.borderColor=d?'rgba(0,200,150,.3)':'var(--b2)';
          var ns='font-size:14px;font-weight:700;color:'+(d?'var(--t3)':'var(--t1)')+';text-decoration:'+(d?'line-through':'none');
          capInfo.innerHTML='<div style="'+ns+'">'+capEx[0]+'</div>'
            +'<div style="font-size:11px;color:var(--orange);font-weight:600;margin-top:1px">'+capEx[1]+'</div>'
            +'<div style="font-size:11px;color:var(--t3);margin-top:2px;line-height:1.4">'+capEx[2]+'</div>';
          // Update progress bar
          var dc=Object.values(day.done).filter(Boolean).length;
          var pb=container.querySelector('div[style*="background:var(--green);height:100%"]');
          if(pb) pb.style.width=Math.round(dc/total*100)+'%';
          var pcEl=container.querySelectorAll('[style*="font-weight:700;color:var(--t2)"]')[0];
          if(pcEl) pcEl.textContent=dc+' / '+total;
        }
        capChk.addEventListener('click', toggleMob);
        capCard.addEventListener('click', function(e){ if(e.target===capCard||e.target.parentNode===capCard) toggleMob(); });
      })(idx, card, chk, info, ex);
    });

    container.appendChild(sec);
  });

  // Progression Tracker
  var progSec=document.createElement('div');
  progSec.style.cssText='padding:0 16px 8px';
  var progHdr=document.createElement('div');
  progHdr.style.cssText='font-size:11px;font-weight:700;color:var(--t3);text-transform:uppercase;letter-spacing:.8px;padding:10px 0 10px';
  progHdr.textContent='📈 Progression Tracker';
  progSec.appendChild(progHdr);

  if(!st.mobProg) st.mobProg={};

  MOB_PROG.forEach(function(prog){
    var key=prog[2];
    var history=st.mobProg[key]||[];
    var latest=history.length?history[history.length-1]:null;

    var card=document.createElement('div');
    card.style.cssText='background:var(--s2);border-radius:14px;padding:14px;margin-bottom:8px;border:1px solid var(--b2)';

    var topRow=document.createElement('div');
    topRow.style.cssText='display:flex;align-items:center;justify-content:space-between;margin-bottom:8px';
    topRow.innerHTML='<div style="font-size:13px;font-weight:700;color:var(--t1)">'+prog[0]+'</div>'
      +(latest?'<div style="font-size:13px;font-weight:800;color:var(--orange)">'+latest.v+' <span style="font-size:10px;color:var(--t3)">'+prog[1]+'</span></div>':'<div style="font-size:11px;color:var(--t3)">No entries yet</div>');

    var inputRow=document.createElement('div');
    inputRow.style.cssText='display:flex;gap:8px;align-items:center';
    var inp=document.createElement('input');
    inp.type='number'; inp.placeholder='Log today ('+prog[1]+')';
    inp.style.cssText='flex:1;background:var(--s1);border:1px solid var(--b2);border-radius:8px;padding:8px 10px;color:var(--t1);font-size:13px;font-family:inherit';
    var logBtn=document.createElement('button');
    logBtn.style.cssText='background:rgba(252,76,2,.1);border:1px solid rgba(252,76,2,.2);color:var(--orange);font-size:12px;font-weight:700;padding:8px 14px;border-radius:8px;cursor:pointer;font-family:inherit;white-space:nowrap';
    logBtn.textContent='Log';

    // Mini history (last 5)
    var histEl=document.createElement('div');
    histEl.style.cssText='margin-top:8px;display:flex;gap:6px;flex-wrap:wrap';
    history.slice(-5).forEach(function(h){
      var chip=document.createElement('span');
      chip.style.cssText='font-size:10px;background:var(--s3);border-radius:6px;padding:2px 7px;color:var(--t3)';
      chip.textContent=h.d+': '+h.v;
      histEl.appendChild(chip);
    });

    (function(capKey, capInp, capTopRow, capProg, capHistEl){
      logBtn.onclick=function(){
        var v=parseFloat(capInp.value);
        if(isNaN(v)) return;
        if(!st.mobProg) st.mobProg={};
        if(!st.mobProg[capKey]) st.mobProg[capKey]=[];
        var today2=getTodayKey();
        // Replace today's entry if exists
        var arr=st.mobProg[capKey];
        var ti=arr.findIndex(function(x){return x.d===today2;});
        if(ti>=0) arr[ti].v=v; else arr.push({d:today2,v:v});
        sv();
        capInp.value='';
        capTopRow.innerHTML='<div style="font-size:13px;font-weight:700;color:var(--t1)">'+capProg[0]+'</div>'
          +'<div style="font-size:13px;font-weight:800;color:var(--orange)">'+v+' <span style="font-size:10px;color:var(--t3)">'+capProg[1]+'</span></div>';
        // Refresh history chips
        capHistEl.innerHTML='';
        st.mobProg[capKey].slice(-5).forEach(function(h){
          var chip=document.createElement('span');
          chip.style.cssText='font-size:10px;background:var(--s3);border-radius:6px;padding:2px 7px;color:var(--t3)';
          chip.textContent=h.d+': '+h.v;
          capHistEl.appendChild(chip);
        });
        toast('Logged: '+v+' '+capProg[1]);
      };
    })(key, inp, topRow, prog, histEl);

    inputRow.appendChild(inp); inputRow.appendChild(logBtn);
    card.appendChild(topRow); card.appendChild(inputRow);
    if(history.length) card.appendChild(histEl);
    progSec.appendChild(card);
  });
  container.appendChild(progSec);

  // Notes
  var noteWrap=document.createElement('div');
  noteWrap.style.cssText='padding:0 16px 20px';
  var noteLbl=document.createElement('div');
  noteLbl.style.cssText='font-size:12px;font-weight:700;color:var(--t3);text-transform:uppercase;letter-spacing:.5px;margin-bottom:8px';
  noteLbl.textContent='Notes';
  var noteTA=document.createElement('textarea');
  noteTA.style.cssText='width:100%;background:var(--s2);border:1px solid var(--b2);border-radius:12px;padding:12px;color:var(--t1);font-size:13px;font-family:inherit;resize:none;box-sizing:border-box';
  noteTA.rows=3; noteTA.placeholder='How did it feel? Any tight spots?';
  noteTA.value=day.notes||'';
  noteTA.oninput=function(){ day.notes=this.value; sv(); };
  noteWrap.appendChild(noteLbl); noteWrap.appendChild(noteTA);
  container.appendChild(noteWrap);
}

