      var heading=headingMatch?headingMatch[1]:lines[0].replace(/^\\d+\\.\\s*/,'').replace(/[:\\s]*$/,'');
      var firstLineRemainder=lines[0].replace(/^\\d+\\.\\s*[A-Z ]+[:\\s]*/,'').trim();
      var bodyText=lines.slice(1).join(' ').trim()||firstLineRemainder||lines[0];
